        children: "-- Sample schema\r\nCREATE TABLE employees (\r\n    id SERIAL PRIMARY KEY,\r\n    name VARCHAR(100),\r\n    department_id INTEGER,\r\n    salary DECIMAL(10,2)\r\n);\r\n\r\nCREATE TABLE departments (\r\n    id SERIAL PRIMARY KEY,\r\n    name VARCHAR(100)\r\n);\r\n\r\nCREATE TABLE projects (\r\n    id SERIAL PRIMARY KEY,\r\n    name VARCHAR(100),\r\n    employee_id INTEGER REFERENCES employees(id)\r\n);\r\n\r\n-- Anti-join: employees without projects\r\nSELECT e.*\r\nFROM employees e\r\nLEFT JOIN projects p ON e.id = p.employee_id\r\nWHERE p.id IS NULL;\r\n\r\n-- Equivalent with NOT EXISTS\r\nSELECT e.*\r\nFROM employees e\r\nWHERE NOT EXISTS (\r\n    SELECT 1 FROM projects p WHERE p.employee_id = e.id\r\n);\r\n\r\n-- Semi-join: employees with projects (using EXISTS)\r\nSELECT e.*\r\nFROM employees e\r\nWHERE EXISTS (\r\n    SELECT 1 FROM projects p WHERE p.employee_id = e.id\r\n);\r\n\r\n-- Self-join: employees earning more than their manager\r\nSELECT e.name AS employee, e.salary, m.name AS manager, m.salary AS manager_salary\r\nFROM employees e\r\nJOIN employees m ON e.manager_id = m.id\r\nWHERE e.salary > m.salary;\n"
